from itertools import product, combinations
import heapq


def ledger(data, priority, tax_base, refund):
    def rounded(n):
        if data["rounding"] == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if priority == "revision_first":
            key = (event.get("revision", 0), pos)
        else:
            key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if tax_base == "discounted" else raw
        total = net + rounded(base * event.get("tax_bp", 0))
        if refund and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best_installation = None
    for selection in product(*choices):
        installed = {name: row for name, row in zip(names, selection)
                     if row is not None}
        edges = {}
        reached = set()
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            row = installed.get(name)
            if row is None:
                valid = False
                break
            version = row["version"]
            if name in data["roots"]:
                low, high = data["roots"][name]
                if not low <= version <= high:
                    valid = False
                    break
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_row = installed.get(other)
                if other_row is None or not dep["min"] <= other_row["version"] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
                if other not in reached:
                    pending.append(other)
        if not valid or reached != set(installed):
            continue

        active, done = set(), set()

        def acyclic(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True

        if not all(acyclic(name) for name in edges):
            continue
        vector = tuple(installed[name]["version"] if name in installed else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = {name: installed[name]["version"]
                                 for name in names if name in installed}

    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def quota_solver(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids:
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        timeline = []
        for job in subset:
            timeline.append((job["start"], 1))
            timeline.append((job["end"], -1))
        active = 0
        feasible = True
        for _, change in sorted(timeline):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        ordered_ids = tuple(sorted(ids))
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ordered_ids < best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def route_solver(data):
    required = data.get("required", [])
    bit_for = {}
    for index, node in enumerate(required):
        bit_for[node] = bit_for.get(node, 0) | (1 << index)
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], *start_state)]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(coupons, edge["duration"])]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((coupons - 1, duration))
            for remaining, duration in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_state = (next_node, mask | bit_for.get(next_node, 0), remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


